
CREATE TABLE patients (patient_id VARCHAR(30) PRIMARY KEY, age_group VARCHAR(30), sex CHAR(1), data_status VARCHAR(20) NOT NULL DEFAULT 'SYNTHETIC');
CREATE TABLE providers (provider_id VARCHAR(30) PRIMARY KEY, provider_name VARCHAR(120) NOT NULL, provider_type VARCHAR(30) NOT NULL, data_status VARCHAR(20) NOT NULL DEFAULT 'SYNTHETIC');
CREATE TABLE encounters (encounter_id VARCHAR(30) PRIMARY KEY, patient_id VARCHAR(30) NOT NULL REFERENCES patients(patient_id), provider_id VARCHAR(30) NOT NULL REFERENCES providers(provider_id), service_date DATE NOT NULL, encounter_type VARCHAR(30) NOT NULL, data_status VARCHAR(20) NOT NULL DEFAULT 'SYNTHETIC');
CREATE TABLE diagnoses (diagnosis_id VARCHAR(40) PRIMARY KEY, encounter_id VARCHAR(30) NOT NULL REFERENCES encounters(encounter_id), diagnosis_code VARCHAR(30) NOT NULL, diagnosis_role VARCHAR(20), data_status VARCHAR(20) NOT NULL DEFAULT 'SYNTHETIC');
CREATE TABLE procedures (procedure_id VARCHAR(40) PRIMARY KEY, encounter_id VARCHAR(30) NOT NULL REFERENCES encounters(encounter_id), procedure_code VARCHAR(50) NOT NULL, procedure_date DATE, quantity_supported NUMERIC(12,2) NOT NULL DEFAULT 0, record_status VARCHAR(30) NOT NULL, claim_item_id VARCHAR(40), data_status VARCHAR(20) NOT NULL DEFAULT 'SYNTHETIC');
CREATE TABLE claims (claim_id VARCHAR(30) PRIMARY KEY, encounter_id VARCHAR(30) NOT NULL REFERENCES encounters(encounter_id), provider_id VARCHAR(30) NOT NULL REFERENCES providers(provider_id), claim_date DATE NOT NULL, claim_status VARCHAR(30) NOT NULL, total_amount NUMERIC(18,2) NOT NULL DEFAULT 0, data_status VARCHAR(20) NOT NULL DEFAULT 'SYNTHETIC');
CREATE TABLE claim_items (claim_item_id VARCHAR(40) PRIMARY KEY, claim_id VARCHAR(30) NOT NULL REFERENCES claims(claim_id), sequence_no INT NOT NULL, service_code VARCHAR(50) NOT NULL, service_type VARCHAR(50) NOT NULL, quantity NUMERIC(12,2) NOT NULL, unit_price NUMERIC(18,2) NOT NULL, net_amount NUMERIC(18,2) NOT NULL, encounter_id VARCHAR(30) NOT NULL REFERENCES encounters(encounter_id), ground_truth_item_status VARCHAR(30), UNIQUE (claim_id, sequence_no));
CREATE TABLE billing_items (billing_id VARCHAR(40) PRIMARY KEY, claim_id VARCHAR(30) NOT NULL REFERENCES claims(claim_id), claim_item_id VARCHAR(40) NOT NULL REFERENCES claim_items(claim_item_id), item_code VARCHAR(50) NOT NULL, quantity NUMERIC(12,2) NOT NULL, amount NUMERIC(18,2) NOT NULL, data_status VARCHAR(20) NOT NULL DEFAULT 'SYNTHETIC');
CREATE TABLE evidence_links (evidence_link_id VARCHAR(40) PRIMARY KEY, claim_item_id VARCHAR(40) NOT NULL REFERENCES claim_items(claim_item_id), evidence_type VARCHAR(50) NOT NULL, source_id VARCHAR(50), match_status VARCHAR(30) NOT NULL, match_quantity NUMERIC(12,2) NOT NULL DEFAULT 0, availability VARCHAR(20) NOT NULL, reason TEXT, data_status VARCHAR(20) NOT NULL DEFAULT 'SYNTHETIC');
CREATE TABLE risk_signals (signal_id VARCHAR(40) PRIMARY KEY, claim_id VARCHAR(30) NOT NULL REFERENCES claims(claim_id), claim_item_id VARCHAR(40) REFERENCES claim_items(claim_item_id), signal_type VARCHAR(50) NOT NULL, severity VARCHAR(20) NOT NULL, reason_code VARCHAR(50), reason_detail TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, data_status VARCHAR(20) NOT NULL DEFAULT 'SYNTHETIC');
CREATE TABLE cases (case_id VARCHAR(40) PRIMARY KEY, claim_id VARCHAR(30) NOT NULL REFERENCES claims(claim_id), primary_risk_mode VARCHAR(50) NOT NULL, review_priority VARCHAR(20) NOT NULL, case_status VARCHAR(30) NOT NULL DEFAULT 'OPEN', affected_items TEXT, evidence_gap NUMERIC(12,2), evidence_coverage_pct NUMERIC(6,2), review_focus TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, data_status VARCHAR(20) NOT NULL DEFAULT 'SYNTHETIC');
CREATE TABLE review_outcomes (review_id VARCHAR(40) PRIMARY KEY, case_id VARCHAR(40) NOT NULL REFERENCES cases(case_id), reviewer_id VARCHAR(50) NOT NULL, outcome VARCHAR(40) NOT NULL, notes TEXT, reviewed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, data_status VARCHAR(20) NOT NULL DEFAULT 'SYNTHETIC');
CREATE TABLE audit_logs (audit_id BIGSERIAL PRIMARY KEY, case_id VARCHAR(40) REFERENCES cases(case_id), actor_id VARCHAR(50) NOT NULL, action VARCHAR(50) NOT NULL, detail TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_claim_items_claim_id ON claim_items(claim_id); CREATE INDEX idx_evidence_links_claim_item ON evidence_links(claim_item_id); CREATE INDEX idx_risk_signals_claim ON risk_signals(claim_id); CREATE INDEX idx_cases_priority_status ON cases(review_priority, case_status);
